import telnetlib


class WindowsTelnetConnection(object):
    def __init__(self, host, username, password, timeout, close_on_exit=False):
        self.close_on_exit = close_on_exit
        self.host = host
        self.username = username
        self.password = password
        self.timeout = timeout
        self.telnet = None

    def __enter__(self):
        if self.telnet is not None:
            return self.telnet
        try:
            self.telnet = self._create_py3_compatible_telnet()
            self.telnet.open(self.host)

            self._disable_echoing()
            self._send_username()
            self._send_password()
            self._await_banner()
        except Exception:
            self.telnet = None
            raise

        return self.telnet

    def __exit__(self, *args):
        if self.close_on_exit and self.telnet:
            self.telnet.close()
            self.telnet = None

    def __del__(self):
        if self.telnet:
            self.telnet.close()

    @staticmethod
    def _create_py3_compatible_telnet():
        telnet = telnetlib.Telnet()
        encoding = 'utf-8'

        def write_bytes(message):
            telnet._write(message.encode(encoding))
        telnet._write = telnet.write
        telnet.write = write_bytes

        def expect_bytes(expected, timeout=None):
            expected = [e.encode(encoding) if isinstance(e, str) else e
                        for e in expected]
            result = telnet._expect(expected, timeout=timeout)
            idx_of_expected, match_object, matched_string = result
            if isinstance(matched_string, bytes):
                result = (idx_of_expected, match_object, str(matched_string))
            return result
        telnet._expect = telnet.expect
        telnet.expect = expect_bytes

        def read_until_bytes(expected, timeout=None):
            expected = expected.encode(encoding)
            return telnet._read_until(expected, timeout=timeout)
        telnet._read_until = telnet.read_until
        telnet.read_until = read_until_bytes

        return telnet

    def _disable_echoing(self):
        i_will_echo = telnetlib.IAC + telnetlib.WILL + telnetlib.ECHO
        self._write_raw_sequence(i_will_echo)

    def _write_raw_sequence(self, seq):
        sock = self.telnet.get_socket()
        if sock is not None:
            sock.send(seq)

    def _send_username(self):
        _, matched, _ = self.telnet.expect(['login:'], self.timeout)
        if matched is None:
            raise RuntimeError("expected 'login:' string was not received.")
        self.telnet.write(self.username + '\r\n')

    def _send_password(self):
        _, matched, _ = self.telnet.expect(['password:'], self.timeout)
        if matched is None:
            raise RuntimeError("expected 'password:' string was not received.")
        self.telnet.write(self.password + '\r\n')

    def _await_banner(self):
        expected_responses = ['Microsoft Telnet Server.\r\n\\*=*\r\n.*>',
                              'Login Failed\r\n',
                              'Denying new connections']
        response_idx, _, _ = self.telnet.expect(expected_responses,
                                                self.timeout)
        if response_idx == 1:
            raise ValueError("incorrect username or password - login failed.")
        elif response_idx == 2:
            exc_msg = "server denied new connection "
            exc_msg += "(too many connections already opened?)."
            raise RuntimeError(exc_msg)
        if response_idx == -1:
            raise RuntimeError("expected telnet banner was not received.")
